import{_ as l,a0 as u,w as i,s as d,ao as p,I as o,a1 as n,A as r,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const R=JSON.parse('{"title":"如何在linux上通過GRUB添加內核參數 | LCTT x X-CMD","titleTemplate":false,"description":"如何在linux上通過GRUB添加內核參數 | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在linux上通過GRUB添加內核參數 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在linux上通過GRUB添加內核參數 | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/How to add kernel boot parameters via GRUB on Linux","title":"如何在linux上通過GRUB添加內核參數","tag":"201311","desc":""},"relativePath":"201311/How to add kernel boot parameters via GRUB on Linux.md","filePath":"[post].md"}'),s={name:"201311/How to add kernel boot parameters via GRUB on Linux.md"};function m(b,e,f,x,g,U){const a=u("Link");return i(),d("div",null,[e[12]||(e[12]=p(`<h1 id="如何在linux上通過grub添加內核參數" tabindex="-1">如何在linux上通過GRUB添加內核參數 <a class="header-anchor" href="#如何在linux上通過grub添加內核參數" aria-label="Permalink to “如何在linux上通過GRUB添加內核參數”">​</a></h1><p>我們可以在linux內核啓動時為其提供各種各樣的參數。這些參數可以自定義內核默認的行為，或者通知內核關於硬件的配置信息。內核參數應在內核啓動時通過引導裝載程序，如GRUB或LILO傳遞給內核。</p><p>在本教程中，我將會描述<strong>如何在linux上通過GRUB添加內核參數</strong>。</p><p>如果你在使用GRUB引導裝載程序，想修改或添加內核參數，你可以編輯GRUB配置文件。下面是針對特定發行版在GRUB的配置文件中添加內核啓動參數的方法。</p><h3 id="在debian或ubuntu上添加內核啓動參數" tabindex="-1">在Debian或Ubuntu上添加內核啓動參數### <a class="header-anchor" href="#在debian或ubuntu上添加內核啓動參數" aria-label="Permalink to “在Debian或Ubuntu上添加內核啓動參數###”">​</a></h3><p>在基於Debian的系統上，如果你想在系統啓動時添加內核參數，你可以編輯 /etc/default/grub 目錄下的GRUB配置模板。在 GRUB_CMDLINE_LINUX_DEFAULT 變量中以 “name=value” 的格式添加內核參數。</p><pre><code>$ sudo -e /etc/default/grub 
</code></pre><blockquote><p>GRUB_CMDLINE_LINUX_DEFAULT=&quot;...... name=value&quot;</p></blockquote><p>然後運行下面的命令來生成一個GRUB的配置文件。</p><pre><code>$ sudo update-grub 
</code></pre><p>如果無法找到 update-grub 命令，你可以通過下面的命令安裝它。</p><pre><code>$ sudo apt-get install grub2-common 
</code></pre><h3 id="在fedora上添加內核啓動參數" tabindex="-1">在Fedora上添加內核啓動參數 <a class="header-anchor" href="#在fedora上添加內核啓動參數" aria-label="Permalink to “在Fedora上添加內核啓動參數”">​</a></h3><p>在Fedora上，想要在啓動時添加內核參數，你可以編輯 /etc/default/grub目錄下的 GRUB 配置模板。在 GRUB_CMDLINE_LINUX 變量中以 “name=value” 的格式添加內核參數。</p><pre><code>$ sudo -e /etc/default/grub 
</code></pre><blockquote><p>GRUB_CMDLINE_LINUX=&quot;...... name=value&quot;</p></blockquote><p>然後運行下面的命令生成 GRUB2 配置文件。</p><pre><code>$ sudo grub2-mkconfig -o /boot/grub2/grub.cfg
</code></pre><h3 id="在centos上添加內核啓動參數" tabindex="-1">在CentOS上添加內核啓動參數 <a class="header-anchor" href="#在centos上添加內核啓動參數" aria-label="Permalink to “在CentOS上添加內核啓動參數”">​</a></h3><p>在CentOS上，想要在啓動時添加內核參數，你可以直接編輯GRUB配置文件 /boot/grub/grub.conf。在配置文件中，找到描述默認使用的Linux映像的條目。文件中最頂行的字符串 “default=N”會指示哪一個條目是默認的映像。</p>`,20)),o("p",null,[n(a,{href:"http://www.flickr.com/photos/xmodulo/10618657834/"},{default:r(()=>[...e[0]||(e[0]=[o("img",{src:"http://farm8.staticflickr.com/7429/10618657834_8082c2806b_z.jpg",alt:""},null,-1)])]),_:1})]),e[13]||(e[13]=o("p",null,"找到默認的映像條目後，在以 “kernel /vmlinuz-” 開頭的那一段的結尾附加上內核參數。參數的格式為 “name=value” 。",-1)),e[14]||(e[14]=o("hr",null,null,-1)),o("p",null,[e[2]||(e[2]=t("via: ",-1)),n(a,{href:"http://xmodulo.com/2013/11/add-kernel-boot-parameters-via-grub-linux.html"},{default:r(()=>[...e[1]||(e[1]=[t("http://xmodulo.com/2013/11/add-kernel-boot-parameters-via-grub-linux.html",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("譯者：",-1)),n(a,{href:"https://github.com/Linchenguang"},{default:r(()=>[...e[3]||(e[3]=[t("Linchenguang",-1)])]),_:1}),e[6]||(e[6]=t(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:r(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[9]||(e[9]=t("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[7]||(e[7]=[t("LCTT",-1)])]),_:1}),e[10]||(e[10]=t(" 原創翻譯，",-1)),n(a,{href:"http://linux.cn/"},{default:r(()=>[...e[8]||(e[8]=[t("Linux中國",-1)])]),_:1}),e[11]||(e[11]=t(" 榮譽推出",-1))])])}const G=l(s,[["render",m]]);export{R as __pageData,G as default};
